
import React, { useState, useEffect, useRef, useCallback } from 'react';
import * as XLSX from 'xlsx';
import { saveAs } from 'file-saver';
import './App.css';


// ── Color palette ────────────────────────────────────────────────────────────
const PALETTE = [
  '#3B82F6','#EF4444','#10B981','#F59E0B','#8B5CF6',
  '#EC4899','#14B8A6','#F97316','#6366F1','#84CC16',
];
let _ci = 0;
const nextColor = () => PALETTE[_ci++ % PALETTE.length];

// ── Default portfolio data ───────────────────────────────────────────────────
const DEFAULT_CHARTS = [
  {
    title: '리밸런싱 전',
    categories: [
      { name: '현금성', color: '#8b9fb4', items: [
        { name: '현금',   price: 1000 },
        { name: '예금',   price: 2000 },
      ]},
      { name: '투자', color: '#e8a03a', items: [
        { name: '구글', price: 1000 },
        { name: '애플', price: 2000 },
      ]},
    ],
  },
  {
    title: '리밸런싱 후',
    categories: [
      {
        name: '현금성', color: '#8b9fb4', ratio: 30, items: [
          { name: '현금',   price: 500, ratio: 33.3 },
          { name: '예금',   price: 1000, ratio: 66.7 },
        ],
      },
      {
        name: '투자', color: '#e8a03a', ratio: 70, items: [
          { name: '구글', price: 1500, ratio: 42.9 },
          { name: '애플', price: 2000, ratio: 57.1 },
        ],
      },
    ],
  },
];

// ── SVG donut arc path ───────────────────────────────────────────────────────
function arcPath(cx, cy, r, R, a1, a2) {
  const rad = d => (d - 90) * Math.PI / 180;
  const px  = (rd, a) => (cx + rd * Math.cos(rad(a))).toFixed(3);
  const py  = (rd, a) => (cy + rd * Math.sin(rad(a))).toFixed(3);
  const la  = (a2 - a1) > 180 ? 1 : 0;
  return [
    `M${px(r,a1)},${py(r,a1)}`,
    `L${px(R,a1)},${py(R,a1)}`,
    `A${R},${R} 0 ${la} 1 ${px(R,a2)},${py(R,a2)}`,
    `L${px(r,a2)},${py(r,a2)}`,
    `A${r},${r} 0 ${la} 0 ${px(r,a1)},${py(r,a1)} Z`,
  ].join(' ');
}

// ── Compute unified portfolio data from 2 charts ────────────────────────────
function computePortfolioData(charts) {
  if (charts.length < 2) return null;
  const bChart = charts[0];
  const aChart = charts[1];
  const totalB = bChart.categories.flatMap(c => c.items).reduce((s, i) => s + Number(i.price), 0);
  const totalA = aChart.categories.flatMap(c => c.items).reduce((s, i) => s + Number(i.price), 0);
  if (!totalB || !totalA) return null;
  const catNames = [...new Set([
    ...bChart.categories.map(c => c.name),
    ...aChart.categories.map(c => c.name),
  ])];
  return catNames.map(catName => {
    const bCat = bChart.categories.find(c => c.name === catName);
    const aCat = aChart.categories.find(c => c.name === catName);
    const color = (bCat || aCat).color;
    const itemNames = [...new Set([
      ...(bCat?.items.map(i => i.name) || []),
      ...(aCat?.items.map(i => i.name) || []),
    ])];
    return {
      name: catName, color,
      totBefore: bCat ? bCat.items.reduce((s, i) => s + Number(i.price), 0) / totalB * 100 : 0,
      totAfter:  aCat ? aCat.items.reduce((s, i) => s + Number(i.price), 0) / totalA * 100 : 0,
      items: itemNames.map(itemName => {
        const bItem  = bCat?.items.find(i => i.name === itemName);
        const aItem  = aCat?.items.find(i => i.name === itemName);
        const bPrice = Number(bItem?.price || 0);
        const aPrice = Number(aItem?.price || 0);
        return { name: itemName, before: +(bPrice / totalB * 100).toFixed(1), after: +(aPrice / totalA * 100).toFixed(1) };
      }),
    };
  });
}

// ── DonutChart component (inline SVG) ───────────────────────────────────────
function DonutChart({ cats, mode, selItem, openCat, onSegmentClick }) {
  const isDetail = selItem !== null;
  const segs = [];
  let angle = 0;
  if (isDetail) {
    const allItems = cats.flatMap(cat => cat.items.map(item => ({ cat, item })));
    const totalPct = allItems.reduce((s, { item }) => s + (mode === 'before' ? item.before : item.after), 0);
    allItems.forEach(({ cat, item }) => {
      const pct   = (mode === 'before' ? item.before : item.after) / totalPct * 100;
      const sweep = pct * 3.6;
      if (sweep < 0.2) { angle += sweep; return; }
      const isSel   = selItem.catName === cat.name && selItem.itemName === item.name;
      const sameCat = selItem.catName === cat.name;
      const opacity = isSel ? 1 : sameCat ? 0.4 : 0.18;
      const pop     = isSel ? 7 : 0;
      const mid = angle + sweep / 2;
      const ox = pop * Math.cos((mid - 90) * Math.PI / 180);
      const oy = pop * Math.sin((mid - 90) * Math.PI / 180);
      segs.push({ d: arcPath(60+ox, 60+oy, 30, 54, angle, angle+sweep-0.4), fill: cat.color, opacity, catName: cat.name, itemName: item.name });
      angle += sweep;
    });
  } else {
    const totalPct = cats.reduce((s, cat) => s + (mode === 'before' ? cat.totBefore : cat.totAfter), 0);
    cats.forEach(cat => {
      const pct   = (mode === 'before' ? cat.totBefore : cat.totAfter) / totalPct * 100;
      const sweep = pct * 3.6;
      if (sweep < 0.2) { angle += sweep; return; }
      const isOpen  = openCat === cat.name;
      const opacity = openCat ? (isOpen ? 1 : 0.22) : 1;
      const pop     = isOpen ? 7 : 0;
      const mid = angle + sweep / 2;
      const ox = pop * Math.cos((mid - 90) * Math.PI / 180);
      const oy = pop * Math.sin((mid - 90) * Math.PI / 180);
      segs.push({ d: arcPath(60+ox, 60+oy, 30, 54, angle, angle+sweep-0.4), fill: cat.color, opacity, catName: cat.name, itemName: null });
      angle += sweep;
    });
  }
  return (
    <svg viewBox="0 0 120 120" style={{ width: '100%', height: '100%' }}>
      {segs.map((s, i) => (
        <path key={i} d={s.d} fill={s.fill} opacity={s.opacity}
          style={{ cursor: 'pointer', transition: 'opacity 0.3s' }}
          onClick={() => onSegmentClick(s.catName, s.itemName)} />
      ))}
    </svg>
  );
}

function App() {
  const [charts,     setCharts]     = useState(DEFAULT_CHARTS);
  const [openCat,    setOpenCat]    = useState(null);
  const [selItem,    setSelItem]    = useState(null);   // { catName, itemName }
  const [editModal,  setEditModal]  = useState(false);
  const [editMode,   setEditMode]   = useState('after'); // 'before' | 'after'
  const [barAnimKey, setBarAnimKey] = useState(0);
  const fileInputRef = useRef();

  const cats = computePortfolioData(charts);

  // Re-trigger bar animation when drawer opens
  useEffect(() => { setBarAnimKey(k => k + 1); }, [openCat]);

  // ── Center text ──────────────────────────────────────────────────────────
  let centerBefore = null;
  let centerAfter  = null;
  if (selItem && cats) {
    const cat  = cats.find(c => c.name === selItem.catName);
    const item = cat?.items.find(i => i.name === selItem.itemName);
    if (item) {
      centerBefore = { label: item.name, val: `${item.before}%`, sub: '포트폴리오 비중' };
      centerAfter  = { label: item.name, val: `${item.after}%`,  sub: '포트폴리오 비중', color: cat.color };
    }
  } else if (openCat && cats) {
    const cat = cats.find(c => c.name === openCat);
    if (cat) {
      centerBefore = { label: openCat, val: `${Math.round(cat.totBefore)}%` };
      centerAfter  = { label: openCat, val: `${Math.round(cat.totAfter)}%`, color: cat.color };
    }
  }

  // ── Interaction handlers ─────────────────────────────────────────────────
  const handleCatClick = useCallback((catName) => {
    setOpenCat(prev => prev === catName ? null : catName);
    setSelItem(null);
  }, []);

  const handleItemClick = useCallback((catName, itemName) => {
    setSelItem(prev =>
      prev?.catName === catName && prev?.itemName === itemName ? null : { catName, itemName }
    );
    setOpenCat(catName);
  }, []);

  const handleSegmentClick = useCallback((catName, itemName) => {
    if (itemName) handleItemClick(catName, itemName);
    else handleCatClick(catName);
  }, [handleCatClick, handleItemClick]);

  // ── Modal editing helpers ────────────────────────────────────────────────
  const chartIdx = editMode === 'before' ? 0 : 1;
  const totalBeforeAmount = charts[0]?.categories.flatMap(c => c.items).reduce((s, i) => s + Number(i.price), 0);

  const addCategory = () => setCharts(prev => prev.map((c, i) => i !== chartIdx ? c : {
    ...c,
    categories: [...c.categories, {
      name: '새 분류',
      color: nextColor(),
      ratio: editMode === 'after' ? 0 : undefined,
      items: [{ name: '새 항목', price: 0, ratio: editMode === 'after' ? 0 : undefined }],
    }],
  }));

  const removeCategory = (catIdx) => setCharts(prev => prev.map((c, i) => i !== chartIdx ? c : {
    ...c, categories: c.categories.filter((_, j) => j !== catIdx),
  }));

  const getCategoryRatio = (cat) => {
    if (cat?.ratio != null && !Number.isNaN(Number(cat.ratio))) return Number(cat.ratio);
    const total = cat.items.reduce((sum, item) => sum + Number(item.price), 0);
    return totalBeforeAmount ? total / totalBeforeAmount * 100 : 0;
  };

  const getItemRatio = (item) => {
    if (item?.ratio != null && !Number.isNaN(Number(item.ratio))) return Number(item.ratio);
    return totalBeforeAmount ? Number(item.price) / totalBeforeAmount * 100 : 0;
  };

  const updateCategory = (catIdx, key, value) => setCharts(prev => prev.map((c, i) => {
    if (i !== chartIdx) return c;
    if (editMode === 'after' && key === 'ratio') {
      const category = c.categories[catIdx];
      if (!category) return c;
      const oldRatio = getCategoryRatio(category);
      const newRatio = Number(value);
      const itemCount = Math.max(category.items.length, 1);
      const itemRatios = category.items.map(item => getItemRatio(item));
      const ratioScale = oldRatio > 0 ? newRatio / oldRatio : 1;
      return {
        ...c,
        categories: c.categories.map((cat, j) => {
          if (j !== catIdx) return cat;
          return {
            ...cat,
            ratio: newRatio,
            items: cat.items.map((item, k) => {
              const newItemRatio = oldRatio > 0
                ? itemRatios[k] * ratioScale
                : newRatio / itemCount;
              return {
                ...item,
                ratio: newItemRatio,
                price: totalBeforeAmount ? totalBeforeAmount * newItemRatio / 100 : item.price,
              };
            }),
          };
        }),
      };
    }
    return {
      ...c,
      categories: c.categories.map((cat, j) => j !== catIdx ? cat : { ...cat, [key]: value }),
    };
  }));

  const changeCategoryRatio = (catIdx, delta) => {
    const category = charts[chartIdx]?.categories[catIdx];
    if (!category) return;
    const current = getCategoryRatio(category);
    updateCategory(catIdx, 'ratio', Math.max(0, Math.min(100, current + delta)));
  };

  const removeCategoryFromAll = (catName) => {
    setCharts(prev => prev.map(chart => ({
      ...chart,
      categories: chart.categories.filter(c => c.name !== catName),
    })));
  };

  const changeItemRatio = (catIdx, itemIdx, delta) => {
    const category = charts[chartIdx]?.categories[catIdx];
    if (!category) return;
    const item = category.items[itemIdx];
    if (!item) return;
    const current = getItemRatio(item);
    updateItem(catIdx, itemIdx, 'ratio', Math.max(0, current + delta));
  };

  const addItem = (catIdx) => setCharts(prev => prev.map((c, i) => i !== chartIdx ? c : {
    ...c, categories: c.categories.map((cat, j) => j !== catIdx ? cat : {
      ...cat, items: [...cat.items, { name: '새 항목', price: 0, ratio: editMode === 'after' ? 0 : undefined }],
    }),
  }));

  const removeItem = (catIdx, itemIdx) => setCharts(prev => prev.map((c, i) => i !== chartIdx ? c : {
    ...c, categories: c.categories.map((cat, j) => j !== catIdx ? cat : {
      ...cat, items: cat.items.filter((_, k) => k !== itemIdx),
    }),
  }));

  const updateItem = (catIdx, itemIdx, key, value) => setCharts(prev => prev.map((c, i) => {
    if (i !== chartIdx) return c;
    if (editMode === 'after' && key === 'ratio') {
      return {
        ...c,
        categories: c.categories.map((cat, j) => {
          if (j !== catIdx) return cat;
          const categoryRatio = getCategoryRatio(cat);
          const ratios = cat.items.map((item, idx) => idx === itemIdx ? Number(value) : getItemRatio(item));
          const sumOther = ratios.reduce((sum, ratio) => sum + ratio, 0) - ratios[itemIdx];
          const remaining = Math.max(categoryRatio - ratios[itemIdx], 0);
          return {
            ...cat,
            items: cat.items.map((item, k) => {
              if (k === itemIdx) {
                return {
                  ...item,
                  ratio: ratios[k],
                  price: totalBeforeAmount ? totalBeforeAmount * ratios[k] / 100 : item.price,
                };
              }
              const itemRatio = sumOther > 0
                ? ratios[k] / sumOther * remaining
                : remaining / Math.max(cat.items.length - 1, 1);
              return {
                ...item,
                ratio: itemRatio,
                price: totalBeforeAmount ? totalBeforeAmount * itemRatio / 100 : item.price,
              };
            }),
          };
        }),
      };
    }
    return {
      ...c,
      categories: c.categories.map((cat, j) => j !== catIdx ? cat : {
        ...cat,
        items: cat.items.map((item, k) => k !== itemIdx ? item : { ...item, [key]: value }),
      }),
    };
  }));


  // ── XLSX save/load ───────────────────────────────────────────────────────
  const saveXLSX = () => {
    const allRows = [];
    charts.forEach((chart) => {
      chart.categories.forEach((cat) => {
        cat.items.forEach(item => {
          allRows.push({
            chart: chart.title,
            category: cat.name,
            color: cat.color,
            categoryRatio: cat.ratio,
            item: item.name,
            itemRatio: item.ratio,
            price: item.price,
          });
        });
      });
    });
    const ws = XLSX.utils.json_to_sheet(allRows);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Sheet1');
    const buf = XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
    saveAs(new Blob([buf], { type: 'application/octet-stream' }), 'asset_allocation.xlsx');
  };

  // ── XLSX load ────────────────────────────────────────────────────────────
  const loadXLSX = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (evt) => {
      const wb       = XLSX.read(new Uint8Array(evt.target.result), { type: 'array' });
      const ws       = wb.Sheets[wb.SheetNames[0]];
      const rows     = XLSX.utils.sheet_to_json(ws);
      const filtered = rows.filter(r => (r.chart || r['차트']) && (r.category || r['자산구분']) && (r.item || r['항목']));
      const chartMap = {};
      filtered.forEach(raw => {
        const cTitle = raw.chart    || raw['차트']    || '차트1';
        const cName  = raw.category || raw['자산구분'] || '분류1';
        const iName  = raw.item     || raw['항목']    || '항목1';
        const price  = Number(raw.price || raw['금액'] || 0);
        const color  = raw.color;
        const categoryRatio = Number(raw.categoryRatio || raw['categoryRatio'] || raw['카테고리비율'] || 0);
        const itemRatio = Number(raw.itemRatio || raw['itemRatio'] || raw['항목비율'] || 0);
        if (!chartMap[cTitle]) chartMap[cTitle] = {};
        if (!chartMap[cTitle][cName]) chartMap[cTitle][cName] = { color: color || nextColor(), ratio: categoryRatio || undefined, items: [] };
        if (categoryRatio && !chartMap[cTitle][cName].ratio) {
          chartMap[cTitle][cName].ratio = categoryRatio;
        }
        chartMap[cTitle][cName].items.push({ name: iName, price, ratio: itemRatio || undefined });
      });
      setCharts(Object.entries(chartMap).map(([title, catMap]) => ({
        title,
        categories: Object.entries(catMap).map(([name, cat]) => ({ name, color: cat.color, items: cat.items })),
      })));
      setOpenCat(null);
      setSelItem(null);
    };
    reader.readAsArrayBuffer(file);
  };

  // ── Bar width (50% portfolio = 100% track) ─────────────────────────────
  const BAR_SCALE = 50;
  const bw = pct => Math.min(pct / BAR_SCALE * 100, 100).toFixed(2);

  return (
    <div className="App">
      <h1 className="app-title">자산 구성</h1>

      <div className="header-actions">
        <button className="btn" onClick={() => setEditModal(true)}>데이터 편집</button>
        <button className="btn btn-secondary" onClick={saveXLSX}>XLSX 저장</button>
        <button className="btn btn-secondary" onClick={() => fileInputRef.current.click()}>XLSX 불러오기</button>
        <input
          type="file" accept=".xlsx" ref={fileInputRef}
          style={{ display: 'none' }}
          onClick={e => (e.target.value = null)}
          onChange={loadXLSX}
        />
      </div>

      {cats && (
        <div className="portfolio-view">

          {/* ── Two donuts ── */}
          <div className="donuts-row">
            <div className="donut-col">
              <span className="donut-label">Before</span>
              <div className="donut-wrap">
                <DonutChart cats={cats} mode="before" selItem={selItem} openCat={openCat} onSegmentClick={handleSegmentClick} />
                <div className="donut-center">
                  {centerBefore ? (
                    <>
                      <span className="dc-label">{centerBefore.label}</span>
                      <span className="dc-val">{centerBefore.val}</span>
                      {centerBefore.sub && <span className="dc-sub">{centerBefore.sub}</span>}
                    </>
                  ) : (
                    <span className="dc-label" style={{ fontSize: 11 }}>{charts[0]?.title}</span>
                  )}
                </div>
              </div>
            </div>

            <span className="arrow-mid">→</span>

            <div className="donut-col">
              <span className="donut-label">After</span>
              <div className="donut-wrap">
                <DonutChart cats={cats} mode="after" selItem={selItem} openCat={openCat} onSegmentClick={handleSegmentClick} />
                <div className="donut-center">
                  {centerAfter ? (
                    <>
                      <span className="dc-label">{centerAfter.label}</span>
                      <span className="dc-val" style={{ color: centerAfter.color }}>{centerAfter.val}</span>
                      {centerAfter.sub && <span className="dc-sub">{centerAfter.sub}</span>}
                    </>
                  ) : (
                    <span className="dc-label" style={{ fontSize: 11 }}>{charts[1]?.title}</span>
                  )}
                </div>
              </div>
            </div>
          </div>

          {/* ── Category legend ── */}
          <div className="legend">
            {cats.map(cat => {
              const isOpen = openCat === cat.name;
              return (
                <div key={cat.name} className="cat-card">
                  <div className={`cat-header${isOpen ? ' open' : ''}`} onClick={() => handleCatClick(cat.name)}>
                    <div className="cat-header-left">
                      <div className="cat-swatch" style={{ background: cat.color }} />
                      <span className="cat-name">{cat.name}</span>
                    </div>
                    <div className="cat-header-right">
                      <div className="pct-group">
                        <span className="pct-before">{Math.round(cat.totBefore)}%</span>
                        <span className="pct-arr">›</span>
                        <span className="pct-after" style={{ color: cat.color }}>{Math.round(cat.totAfter)}%</span>
                      </div>
                      <span className="chevron">›</span>
                    </div>
                  </div>

                  <div className={`item-drawer${isOpen ? ' open' : ''}`}>
                    <div className="drawer-inner">
                      {cat.items.map(item => {
                        const delta    = +(item.after - item.before).toFixed(1);
                        const isNew    = item.before === 0;
                        const isUp     = delta > 0.05;
                        const isDown   = delta < -0.05;
                        const isSel    = selItem?.catName === cat.name && selItem?.itemName === item.name;
                        const badgeText  = isNew ? '신규' : (delta > 0 ? `+${delta}%` : `${delta}%`);
                        const badgeClass = (isNew || isUp) ? 'badge-up' : (isDown ? 'badge-down' : 'badge-same');
                        const aw  = +bw(item.after);
                        const bw_ = +bw(item.before);
                        let fillGradient;
                        if (isNew) {
                          fillGradient = '#22c55e';
                        } else if (isUp) {
                          const pivot = (item.before / item.after * 100).toFixed(1);
                          fillGradient = `linear-gradient(to right,${cat.color} 0%,${cat.color} ${pivot}%,#22c55e ${pivot}%,#22c55e 100%)`;
                        } else {
                          fillGradient = cat.color;
                        }
                        return (
                          <div key={item.name} className={`item-row${isSel ? ' sel' : ''}`} onClick={() => handleItemClick(cat.name, item.name)}>
                            <div className="item-top">
                              <div className="item-dot" style={{ background: cat.color }} />
                              <span className="item-name">{item.name}</span>
                              <span className={`badge ${badgeClass}`}>{badgeText}</span>
                            </div>
                            <div className="bar-track">
                              {isDown && (
                                <div className="bar-ghost" style={{ left: `${aw}%`, width: `${(bw_ - aw).toFixed(2)}%` }} />
                              )}
                              <div
                                key={`bar-${barAnimKey}-${cat.name}-${item.name}`}
                                className="bar-fill"
                                style={{ '--bar-target': `${aw}%`, background: fillGradient }}
                              />
                              {!isNew && item.before > 0 && (
                                <div className="bar-before-marker" style={{ left: `${bw_}%` }} />
                              )}
                            </div>
                            <div className="bar-pcts">
                              <span className="bar-pct-before">{isNew ? '신규 추가' : `전 ${item.before}%`}</span>
                              <span className="bar-pct-after" style={{ color: (isNew || isUp) ? '#1a7f3c' : (isDown ? '#b71c1c' : cat.color) }}>
                                {isNew ? `${item.after}%` : `후 ${item.after}%`}
                              </span>
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* ── Edit Modal ── */}
      {editModal && (
        <div className="modal-overlay" onClick={() => setEditModal(false)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <div className="modal-header">
              <span className="modal-title">데이터 편집</span>
              <button className="btn btn-secondary" onClick={() => setEditModal(false)}>완료</button>
            </div>

            <div className="modal-tabs">
              <button className={`tab-btn${editMode === 'before' ? ' active' : ''}`} onClick={() => setEditMode('before')}>
                {charts[0]?.title || '리밸런싱 전'}
              </button>
              <button className={`tab-btn${editMode === 'after' ? ' active' : ''}`} onClick={() => setEditMode('after')}>
                {charts[1]?.title || '리밸런싱 후'}
              </button>
            </div>

            {editMode === 'after' && (
              <div className="editor-note">
                리밸런싱 후는 비율 입력만 하면 현재 총액 기준으로 금액이 자동 계산됩니다.
              </div>
            )}

            <div className="modal-body">
              {charts[chartIdx]?.categories.map((cat, catIdx) => (
                <div key={catIdx} className="modal-cat-card">
                  <div className="modal-cat-header">
                    <div className="color-dot" style={{ background: cat.color }} />
                    <input
                      className="minimal-input cat-name-input"
                      value={cat.name}
                      onChange={e => updateCategory(catIdx, 'name', e.target.value)}
                    />
                    {editMode === 'after' ? (
                      <div className="category-controls after-controls">
                        <div className="ratio-control">
                          <input
                            className="category-slider"
                            type="range"
                            min={0}
                            max={100}
                            step={0.1}
                            value={getCategoryRatio(cat)}
                            onChange={e => updateCategory(catIdx, 'ratio', Number(e.target.value))}
                          />
                          <div className="ratio-right">
                            <span className="category-ratio-display">{getCategoryRatio(cat).toFixed(1)}%</span>
                          </div>
                        </div>
                        <button className="btn btn-danger btn-sm cat-delete" onClick={() => removeCategoryFromAll(cat.name)}>×</button>
                      </div>
                    ) : (
                      <div className="category-controls before-controls">
                        <div className="color-swatch-row">
                          {PALETTE.map(color => (
                            <div
                              key={color}
                              className={`color-swatch${cat.color === color ? ' selected' : ''}`}
                              style={{ background: color }}
                              onClick={() => updateCategory(catIdx, 'color', color)}
                            />
                          ))}
                        </div>
                        <button className="btn btn-danger btn-sm cat-delete" onClick={() => removeCategoryFromAll(cat.name)}>×</button>
                      </div>
                    )}
                  </div>

                  <table className="items-table">
                    <thead>
                      <tr>
                        <th>항목</th>
                        <th>{editMode === 'after' ? '비율(%)' : '금액'}</th>
                        {editMode === 'after' && <th>금액(자동)</th>}
                        <th />
                      </tr>
                    </thead>
                    <tbody>
                      {cat.items.map((item, itemIdx) => {
                        const categoryRatio = getCategoryRatio(cat);
                        const itemRatio = getItemRatio(item).toFixed(1);
                        const autoAmount = totalBeforeAmount
                          ? (totalBeforeAmount * Number(itemRatio) / 100).toLocaleString()
                          : '0';
                        return (
                          <tr key={itemIdx}>
                            <td>
                              <input
                                className="minimal-input"
                                value={item.name}
                                onChange={e => updateItem(catIdx, itemIdx, 'name', e.target.value)}
                              />
                            </td>
                            <td className="price-cell">
                              <div className="ratio-control ratio-control-right">
                                <input
                                className="minimal-input"
                                type="number"
                                min={0}
                                step={0.1}
                                value={editMode === 'after' ? (itemRatio === '0.0' ? '' : itemRatio) : (item.price === 0 ? '' : item.price)}
                                onChange={e => {
                                  const raw = e.target.value;
                                  if (editMode === 'after') {
                                    updateItem(catIdx, itemIdx, 'ratio', raw === '' ? 0 : Number(raw));
                                  } else {
                                    updateItem(catIdx, itemIdx, 'price', raw === '' ? 0 : Number(raw));
                                  }
                                }}
                              />
                                {editMode === 'after' && (
                                  <div className="ratio-buttons">
                                    <button className="ratio-button" type="button" onClick={() => changeItemRatio(catIdx, itemIdx, -0.1)}>-</button>
                                    <button className="ratio-button" type="button" onClick={() => changeItemRatio(catIdx, itemIdx, 0.1)}>+</button>
                                  </div>
                                )}
                            </div>
                            </td>
                            {editMode === 'after' && <td className="auto-amount-cell">{autoAmount}</td>}
                            <td>
                              {cat.items.length > 1 && (
                                <button className="btn btn-danger btn-sm" onClick={() => removeItem(catIdx, itemIdx)}>×</button>
                              )}
                            </td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                  <button className="add-item-btn" onClick={() => addItem(catIdx)}>+ 항목 추가</button>
                </div>
              ))}
              <button className="add-category-btn" onClick={addCategory}>+ 분류 추가</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default App;
